/**
 * Writes src/data/gemLevels.ts: the level each gem's first level requires, as the reference gem list has it, and the ladder of
 * character levels its gem levels 1 to 25 require (gem levels, DESIGN.md Appendix A). The reference has one ladder for each first level,
 * read here from the reference skill data (`reqs`, ref-extract.ts). A gem whose reference has no skill data takes its first
 * level from the reference gem list; a gem with no reference starts at level 1.
 *
 *   npm run coverage:emit-gem-levels
 *
 * Nothing from the reference reaches src/: the generated file carries our gem ids and numbers only.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { format, resolveConfig } from 'prettier';
import { COVERAGE_DIR, key } from './reference';

export const OUT = resolve(COVERAGE_DIR, '../../src/data/gemLevels.ts');

type Skill = { name: string; reqs?: number[] };
type ListGem = { name: string; level: number };

const json = <T>(file: string): T =>
  JSON.parse(readFileSync(resolve(COVERAGE_DIR, file), 'utf8')) as T;

async function main(): Promise<void> {
  const map = json<{ gems: Record<string, { ref?: string }> }>('map.json').gems;
  const skills = json<{ skills: Skill[] }>('ref-skills.json').skills;
  const list = json<{ gems: ListGem[] }>('ref-list.json').gems;
  const skillOf = (name: string) =>
    skills.find((s) => key(s.name) === key(name)) ??
    skills.find((s) => key(s.name) === key(name.replace(/ Support$/, '')));
  const listOf = (name: string) => list.find((g) => key(g.name) === key(name));

  // The ladder of each first level: the one most of the reference skills starting there follow.
  const counts = new Map<number, Map<string, number>>();
  for (const s of skills) {
    if (!s.reqs || s.reqs.length < 25) continue;
    const by = counts.get(s.reqs[0]) ?? new Map<string, number>();
    const k = s.reqs.join(',');
    by.set(k, (by.get(k) ?? 0) + 1);
    counts.set(s.reqs[0], by);
  }
  const ladderOf = (first: number): number[] | undefined => {
    const by = counts.get(first);
    if (!by) return undefined;
    return [...by.entries()]
      .sort((a, b) => b[1] - a[1])[0][0]
      .split(',')
      .map(Number);
  };

  const start: Record<string, number> = {};
  const notes: string[] = [];
  for (const [id, entry] of Object.entries(map)) {
    if (!entry.ref) continue;
    const fromSkill = skillOf(entry.ref)?.reqs?.[0];
    const fromList = listOf(entry.ref)?.level;
    const first = fromSkill ?? fromList;
    if (first === undefined) {
      notes.push(`${id}: no reference level, starts at 1`);
      continue;
    }
    if (fromSkill !== undefined && fromList !== undefined && fromSkill !== fromList)
      notes.push(`${id}: skill data ${fromSkill}, gem list ${fromList}; kept ${fromSkill}`);
    if (first > 1) start[id] = first;
  }
  const firsts = [...new Set([1, ...Object.values(start)])].sort((a, b) => a - b);
  const ladders: Record<number, number[]> = {};
  for (const f of firsts) {
    const l = ladderOf(f);
    if (!l) throw new Error(`no reference ladder starts at level ${f}`);
    ladders[f] = l;
  }

  const ids = Object.keys(start).sort();
  const src = `// GENERATED by \`npm run coverage:emit-gem-levels\` (scripts/coverage/emit-gem-levels.ts) from the reference gem
// list and skill data: the character level each gem level requires (gem levels, DESIGN.md Appendix A). Do not edit by hand.

/** The character level gem levels 1 to 25 require, by the level the first one requires. */
export const GEM_LADDERS: Readonly<Record<number, readonly number[]>> = {
${firsts.map((f) => `  ${f}: [${ladders[f].join(', ')}],`).join('\n')}
};

/** The level a gem's first level requires, by gem id; a gem not listed starts at 1. */
export const GEM_START: Readonly<Record<string, number>> = {
${ids.map((id) => `  ${id}: ${start[id]},`).join('\n')}
};
`;
  const options = await resolveConfig(OUT);
  writeFileSync(OUT, await format(src, { ...options, filepath: OUT }));
  console.log(
    `gem levels: ${ids.length} gems start above level 1; ladders from ${firsts.join(', ')}`,
  );
  for (const n of notes) console.log(`  ${n}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) void main();
